begin;
select no_plan();
insert into auth.users(id,email)values('ad100000-0000-0000-0000-000000000001','owner@billing.test'),('ad100000-0000-0000-0000-000000000002','desk@billing.test'),('ad100000-0000-0000-0000-000000000003','viewer@billing.test'),('ad100000-0000-0000-0000-000000000004','hk@billing.test');
insert into public.tenants(id,name,slug)values('ad200000-0000-0000-0000-000000000001','Billing Business','advanced-billing');
insert into public.properties(id,tenant_id,name,property_type,timezone,address)values('ad300000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','Billing Hotel','hotel','UTC','Original address'),('ad300000-0000-0000-0000-000000000002','ad200000-0000-0000-0000-000000000001','Other Billing Hotel','hotel','UTC','Other address');
insert into public.tenant_memberships(tenant_id,user_id,role)select 'ad200000-0000-0000-0000-000000000001',u,case when u='ad100000-0000-0000-0000-000000000001'::uuid then 'owner' else 'member' end from(values('ad100000-0000-0000-0000-000000000001'::uuid),('ad100000-0000-0000-0000-000000000002'::uuid),('ad100000-0000-0000-0000-000000000003'::uuid),('ad100000-0000-0000-0000-000000000004'::uuid))v(u);
insert into public.property_memberships(tenant_id,property_id,user_id)select 'ad200000-0000-0000-0000-000000000001','ad300000-0000-0000-0000-000000000001',u from(values('ad100000-0000-0000-0000-000000000002'::uuid),('ad100000-0000-0000-0000-000000000003'::uuid),('ad100000-0000-0000-0000-000000000004'::uuid))v(u);
insert into public.roles(id,tenant_id,key,name)values('ad800000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','finance_viewer','Finance viewer');
insert into public.role_permissions(role_id,permission_key)values('ad800000-0000-0000-0000-000000000001','finance.read');
insert into public.user_roles(property_id,user_id,role_id)select 'ad300000-0000-0000-0000-000000000001',u,r.id from(values('ad100000-0000-0000-0000-000000000002'::uuid,'front_desk'),('ad100000-0000-0000-0000-000000000004'::uuid,'housekeeping'))v(u,k)join public.roles r on r.key=v.k and r.tenant_id is null;
insert into public.user_roles(property_id,user_id,role_id)values('ad300000-0000-0000-0000-000000000001','ad100000-0000-0000-0000-000000000003','ad800000-0000-0000-0000-000000000001');
insert into public.accommodation_types(id,tenant_id,property_id,name,max_occupancy,base_rate)values('ad400000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','ad300000-0000-0000-0000-000000000001','Standard',2,100);
insert into public.accommodation_units(tenant_id,property_id,type_id,name)values('ad200000-0000-0000-0000-000000000001','ad300000-0000-0000-0000-000000000001','ad400000-0000-0000-0000-000000000001','101');
insert into public.guests(id,tenant_id,full_name,email)values('ad500000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','Original Guest','guest@billing.test');
insert into public.menu_categories(id,tenant_id,property_id,name)values('ad900000-0000-0000-0000-000000000001','ad200000-0000-0000-0000-000000000001','ad300000-0000-0000-0000-000000000001','Room service');
insert into public.menu_items(id,tenant_id,property_id,category_id,name,price)values('ad900000-0000-0000-0000-000000000002','ad200000-0000-0000-0000-000000000001','ad300000-0000-0000-0000-000000000001','ad900000-0000-0000-0000-000000000001','Tea',20);
select set_config('test.day',((now() at time zone 'UTC')::date)::text,true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.res',public.create_reservation('ad300000-0000-0000-0000-000000000001','ad500000-0000-0000-0000-000000000001','ad400000-0000-0000-0000-000000000001',current_setting('test.day')::date-1,current_setting('test.day')::date+1)::text,true);
select public.check_in_reservation(current_setting('test.res')::uuid);
select is((public.billing_workspace('ad300000-0000-0000-0000-000000000001')->>'total')::int,1,'in-house stay appears before folio creation');
select is((public.billing_detail('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)#>>'{summary,balance}')::numeric,0::numeric,'unposted stay has zero posted balance');
select is((select count(*)::int from public.folios where property_id='ad300000-0000-0000-0000-000000000001'),0,'read-only billing views do not create folios');
select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000001','post_rooms','{"expected_balance":0}');
select set_config('test.folio',(select id::text from public.folios where reservation_id=current_setting('test.res')::uuid),true);
select is(public.folio_balance(current_setting('test.folio')::uuid),200::numeric,'full booked room nights are posted');
select public.post_room_charges(current_setting('test.res')::uuid);
select is((select count(*)::int from public.folio_items where folio_id=current_setting('test.folio')::uuid),2,'reposting room nights does not duplicate them');
select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000002','charge','{"expected_balance":200,"amount":"50.00","description":"Late checkout fee"}');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000003','credit','{"expected_balance":250,"amount":"10.00","description":"Discount"}')$$,'42501',null,'front desk cannot issue a credit');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.payment',(public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000004','payment','{"expected_balance":250,"amount":"100.00","method":"cash","reference":"","allow_credit":false}')->>'id'),true);
select is((public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000004','payment','{"expected_balance":250,"amount":"100.00","method":"cash","reference":"","allow_credit":false}')->>'id')::uuid,current_setting('test.payment')::uuid,'retry returns original payment even after balance changes');
select is((select count(*)::int from public.payments where folio_id=current_setting('test.folio')::uuid),1,'duplicate submission records only one payment');
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000004','payment','{"expected_balance":250,"amount":"90.00","method":"cash"}')$$,'22023',null,'request ID cannot be reused for different financial details');
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000005','payment','{"expected_balance":250,"amount":"150.00","method":"cash"}')$$,'40001',null,'stale balance is rejected');
select throws_ok($$select public.collect_folio_payment(current_setting('test.folio')::uuid,1.001,'cash')$$,'22023',null,'fractional cents are rejected');
select throws_ok($$select public.collect_folio_payment(current_setting('test.folio')::uuid,'NaN'::numeric,'cash')$$,'22023',null,'NaN is not a payment');
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000006','payment','{"expected_balance":150,"amount":"151.00","method":"cash"}')$$,'22023',null,'overpayment must be explicitly confirmed');
select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000007','payment','{"expected_balance":150,"amount":"150.00","method":"upi","reference":"receipt-one"}');
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000008','payment','{"expected_balance":0,"amount":"10.00","method":"upi","reference":"receipt-one","allow_credit":true}')$$,'23505',null,'same transaction reference cannot record another payment');
select set_config('test.order',public.place_order('ad300000-0000-0000-0000-000000000001','room_service','[{"menu_item_id":"ad900000-0000-0000-0000-000000000002","quantity":1}]',current_setting('test.res')::uuid)::text,true);
select throws_ok($$select public.finalize_invoice(current_setting('test.folio')::uuid)$$,'22023',null,'pending room orders block invoicing');
select public.set_order_status(current_setting('test.order')::uuid,'cancelled');
select set_config('test.invoice',(public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000009','invoice','{"expected_balance":0}')->>'id'),true);
select is(public.finalize_invoice(current_setting('test.folio')::uuid),current_setting('test.invoice')::uuid,'invoice finalization is idempotent');
select is((select count(*)::int from public.invoices where folio_id=current_setting('test.folio')::uuid),1,'only one invoice is issued');
update public.guests set full_name='Changed Guest' where id='ad500000-0000-0000-0000-000000000001';
update public.properties set address='Changed address' where id='ad300000-0000-0000-0000-000000000001';
select is(public.billing_invoice('ad300000-0000-0000-0000-000000000001',current_setting('test.invoice')::uuid)#>>'{snapshot,guest,name}','Original Guest','invoice guest identity is frozen');
select is(public.billing_invoice('ad300000-0000-0000-0000-000000000001',current_setting('test.invoice')::uuid)#>>'{snapshot,property,address}','Original address','invoice hotel details are frozen');
select throws_ok($$select public.post_folio_charge(current_setting('test.res')::uuid,'Late charge',20)$$,'22023',null,'invoiced folio rejects charges');
select throws_ok($$select public.collect_folio_payment(current_setting('test.folio')::uuid,20,'cash')$$,'22023',null,'invoiced folio rejects new payments');
select throws_ok($$select public.place_order('ad300000-0000-0000-0000-000000000001','room_service','[{"menu_item_id":"ad900000-0000-0000-0000-000000000002","quantity":1}]',current_setting('test.res')::uuid)$$,'22023',null,'new room orders cannot race after invoice closure');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.refund_payment(current_setting('test.payment')::uuid,50,'Goodwill refund')$$,'42501',null,'front desk cannot refund');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.refund',(public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000010','refund',jsonb_build_object('expected_balance',0,'amount','50.00','payment_id',current_setting('test.payment'),'reason','Goodwill refund'))->>'id'),true);
select is((select count(*)::int from public.credit_notes where folio_id=current_setting('test.folio')::uuid),1,'post-invoice refund creates a separate credit note');
select is(public.folio_balance(current_setting('test.folio')::uuid),0::numeric,'refund and credit note preserve a settled closed folio');
select is((public.billing_invoice('ad300000-0000-0000-0000-000000000001',current_setting('test.invoice')::uuid)#>>'{snapshot,total}')::numeric,250::numeric,'refund does not rewrite original invoice total');
select is((public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid,'ad600000-0000-0000-0000-000000000010','refund',jsonb_build_object('expected_balance',0,'amount','50.00','payment_id',current_setting('test.payment'),'reason','Goodwill refund'))->>'id')::uuid,current_setting('test.refund')::uuid,'refund retry returns original refund');
select throws_ok($$select public.refund_payment(current_setting('test.payment')::uuid,60,'Too much refund')$$,'22023',null,'refund cannot exceed unrefunded payment');
select is((public.reservation_detail('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)#>>'{finance,balance}')::numeric,0::numeric,'reservation summary accounts for invoice credit notes');
select is(jsonb_typeof(public.billing_export('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)#>'{entries,0,amount}'),'string','CSV export preserves exact decimal amounts as strings');
select is((public.billing_detail('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)#>>'{ledger,6,running_balance}')::numeric,0::numeric,'ledger running balance includes refund and credit note');
select throws_ok($$select public.billing_detail('ad300000-0000-0000-0000-000000000002',current_setting('test.res')::uuid)$$,'P0002',null,'folio detail rejects mixed hotel and reservation IDs');
select is((public.billing_workspace('ad300000-0000-0000-0000-000000000002')#>>'{stats,collected}')::numeric,0::numeric,'collection summary does not mix hotels');
select set_config('test.tiny',public.create_reservation('ad300000-0000-0000-0000-000000000001','ad500000-0000-0000-0000-000000000001','ad400000-0000-0000-0000-000000000001',current_setting('test.day')::date-4,current_setting('test.day')::date-1)::text,true);
reset role;
update public.reservations set total_amount=0.01 where id=current_setting('test.tiny')::uuid;
set local role authenticated;
select public.check_in_reservation(current_setting('test.tiny')::uuid);
select public.billing_run_audit('ad300000-0000-0000-0000-000000000001',current_setting('test.day')::date-3,'ad700000-0000-0000-0000-000000000001');
select is((public.billing_run_audit('ad300000-0000-0000-0000-000000000001',current_setting('test.day')::date-3,'ad700000-0000-0000-0000-000000000002')->>'room_revenue_posted')::numeric,0::numeric,'repeat audit posts no duplicate room charges');
select is((select(summary->>'room_revenue_posted')::numeric from public.night_audits where property_id='ad300000-0000-0000-0000-000000000001' and business_date=current_setting('test.day')::date-3),0.01::numeric,'repeat audit preserves cumulative posted total');
select public.billing_run_audit('ad300000-0000-0000-0000-000000000001',current_setting('test.day')::date-3,'ad700000-0000-0000-0000-000000000001');
select is((select count(*)::int from public.night_audit_runs where property_id='ad300000-0000-0000-0000-000000000001'),2,'retrying same audit request does not add another run');
select public.post_room_charges(current_setting('test.tiny')::uuid);
select is((select coalesce(sum(amount),0) from public.folio_items where folio_id=(select id from public.folios where reservation_id=current_setting('test.tiny')::uuid)),0.01::numeric,'cent distribution preserves exact full-stay total');
select is((select count(*)::int from public.folio_items where folio_id=(select id from public.folios where reservation_id=current_setting('test.tiny')::uuid) and amount<0),0,'rounding never creates a negative final room night');
select throws_ok($$select public.billing_run_audit('ad300000-0000-0000-0000-000000000001',current_setting('test.day')::date+1,'ad700000-0000-0000-0000-000000000003')$$,'22023',null,'future audit is rejected');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select lives_ok($$select public.billing_detail('ad300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)$$,'finance reader can inspect ledger without reservation permissions');
select throws_ok($$select public.billing_action('ad300000-0000-0000-0000-000000000001',current_setting('test.tiny')::uuid,'ad600000-0000-0000-0000-000000000011','payment','{"amount":"1.00","method":"cash","allow_credit":true}')$$,'42501',null,'finance reader cannot record transactions');
select throws_ok($$select public.billing_run_audit('ad300000-0000-0000-0000-000000000001',current_setting('test.day')::date,'ad700000-0000-0000-0000-000000000004')$$,'42501',null,'finance reader cannot run audit');
select set_config('request.jwt.claims','{"sub":"ad100000-0000-0000-0000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.billing_workspace('ad300000-0000-0000-0000-000000000001')$$,'42501',null,'staff without finance access cannot read billing');
reset role;set local role anon;
select throws_ok($$select public.billing_invoice('ad300000-0000-0000-0000-000000000001',current_setting('test.invoice')::uuid)$$,'42501',null,'anonymous caller cannot inspect invoices');
select * from finish();
rollback;
